let scope = true;
let two = NodeMode::Normal;

{
    let mut tiles = row![tile(0, NodeMode::Normal), tile(1, two)]
        .main_axis_size(MainAxisSize::Min)
        .spacing(1);
    let three = tile(2, NodeMode::Normal);
    let four = tile(3, NodeMode::Normal);
    if scope {
