    pub(crate) align: usize,
    pub(crate) color: usize,
    pub(crate) time: i64,
}

impl BigPreview {
    fn style(self, theme: &ThemeData) -> Style {
        [
            &theme.primary,
            &theme.accent,
            &theme.success,
            &theme.warning,
            &theme.info,
        ][self.color]
            .clone()
    }
}

