use rtwk::AnyWidget;
use rtwk::focus::{FocusNode, KeyCombo};
use rtwk::layout::{Border, BorderTitle, BorderType, BoxWidget, SizedBox};
use rtwk::style::ThemeData;
use rtwk_term::{SharedSession, TerminalView};

// Supply a TerminalSession connected to an in-memory program or a PTY.
// Keep the session and focus node in state while rebuilding the view.
fn preview(session: SharedSession, focus: FocusNode, theme: &ThemeData) -> AnyWidget {
    let ignored = ["tab", "shift+tab", "escape", "ctrl+p"]
        .map(|key| KeyCombo::parse(key).expect("gallery key"));
    let terminal = TerminalView::new(session)
        .focus_node(focus)
        .ignored_keys(ignored)
        .wheel_lines(3);
    SizedBox::new(
        Some(82),
        Some(26),
        Some(
            BoxWidget::new()
                .border(Border::all(theme.border.clone()).kind(BorderType::Rounded))
                .title(BorderTitle::new(" shell "))
                .child(terminal)
                .into(),
        ),
    )
    .into()
}

use rtwk::binding::InputListener;
use rtwk::widgets::Text;
use rtwk_core::input::InputEvent;

pub fn build(on_input: impl Fn(String) + 'static) -> InputListener {
    InputListener::new(
        Text::new("Press a key nothing takes, such as x"),
        move |event| {
            match event {
                InputEvent::Key(_)
                | InputEvent::Mouse(_)
                | InputEvent::Paste(_)
                | InputEvent::Focus(_)
                | InputEvent::Resize { .. } => on_input(event.to_string()),
                _ => {}
            }
            false
        },
    )
}

use rtwk::binding::ErrorWidget;
use rtwk::text::Text;
use rtwk::{AnyWidget, column};

pub fn build() -> AnyWidget {
    let fails = true;
    let error = "Bad state: the weather failed to load";
    let weather = if fails { Err(error) } else { Ok("light rain") };
    match weather {
        Ok(forecast) => column![
            Text::new("12°C"),
            Text::new(forecast),
            Text::new("wind 14 km/h")
        ]
        .into(),
        Err(error) => ErrorWidget::new(error).into(),
    }
}

